mapper.select:
SELECT * FROM data_package_stat
WHERE data_package_id = #{dataPackageId} AND generation = #{generation}
FOR UPDATE

mapper.insert:
INSERT INTO data_package_stat (
  data_package_id, generation, unused_count, claimed_count, sent_count,
  delivered_count, retryable_failed_count, unregistered_count,
  updated_at, reconciled_at
) VALUES (
  #{dataPackageId}, #{generation}, #{unusedCount}, #{claimedCount}, #{sentCount},
  #{deliveredCount}, #{retryableFailedCount}, #{unregisteredCount},
  #{updatedAt}, #{reconciledAt}
)

mapper.update:
UPDATE data_package_stat
SET unused_count = unused_count + #{increment},
    updated_at = #{updatedAt}
WHERE data_package_id = #{dataPackageId}
  AND generation = #{generation}

UPDATE data_package_stat
SET unused_count = unused_count + #{affected},
    retryable_failed_count = retryable_failed_count - #{affected},
    updated_at = #{updatedAt}
WHERE data_package_id = #{dataPackageId}
  AND generation = #{generation}
  AND retryable_failed_count >= #{affected}

UPDATE data_package_stat
SET unused_count = unused_count - #{affected},
    claimed_count = claimed_count + #{affected},
    updated_at = #{updatedAt}
WHERE data_package_id = #{dataPackageId}
  AND generation = #{generation}
  AND unused_count >= #{affected}

UPDATE data_package_stat
SET unused_count = unused_count + #{affected},
    claimed_count = claimed_count - #{affected},
    updated_at = #{updatedAt}
WHERE data_package_id = #{dataPackageId}
  AND generation = #{generation}
  AND claimed_count >= #{affected}
